import { Accessor, createContext, createEffect, createMemo, createSignal, Setter, useContext } from "solid-js";
import { createMutable, modifyMutable, reconcile } from "solid-js/store";

import LiveEventManager from "#core/ui/shell/live-event-logic/live-event-logic.js";
import { DatabaseCache } from "#core/ui/utilities/utilities-data.js";
import { AgeSelectModel, useAgeSelectModelContext } from "#core/ui-next/screens/create-game/age-select-model.js";
import {
	PlayerSetupParametersModel,
	SetupParametersModel,
} from "#core/ui-next/screens/create-game/game-parameters-model.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";
import { FullTextSearch } from "#core/ui-next/utilities/search-utils.js";

export interface CivBonusData {
	title: string;
	icon: string;
	text: string;
	plainText?: string;
	description: string;
	kind: string;
	age?: string;
}

export interface TraditionData {
	civic: string;
	title: string;
	text: string;
	plainText?: string;
	age?: string;
}

export interface UnlockedByData {
	text: string;
	isUnlocked: boolean;
	isGameplayUnlock?: boolean;
}

export interface CivInfo {
	civID: string;
	name: string;
	icon: string;
	bgImage: string;
	perAgeAbilities: {
		abilityTextTag: string;
		abilityTitle: string;
		abilityText: string;
		abilityPlainText?: string;
		age: string;
	}[];
	traits: string[];
	buildings: CivBonusData[];
	units: CivBonusData[];
	traditions: TraditionData[];
	isLocked: boolean;
	isOwned: boolean;
	apexAge: string;
	ageName: string;
	ageSortIndex: number;
	fulltext: string;
	colors: HexColor | null;
	introText: string;
	unlocks: string[];
	unlockedBy: UnlockedByData[];
	isCurrentCiv?: boolean;
	isPreviousCiv?: boolean;
}

export interface CivSelectModel {
	civs: CivInfo[];
	randomCiv: CivInfo;
	previousCiv: Accessor<CivInfo | undefined>;
	selectedCiv: Accessor<CivInfo>;
	setSelectedCiv: (civ: CivInfo) => void;
	viewCiv: Accessor<CivInfo | undefined>;
	setViewCiv: (civ: CivInfo | undefined) => void;
	selectNext: () => void;
	selectPrev: () => void;
	// Returns matching civIds
	fulltextSearch: (text: string) => Set<string>;
}

const cachedCivDatabase = new DatabaseCache("config");

interface CivItemRow {
	CivilizationType?: string;
	Kind?: string;
	Type?: string;
	Icon?: string;
	Name?: string;
	Description?: string;
	AgeType?: string;
}

interface CivTagRow {
	CivilizationType?: string;
	CivilizationDomain?: string;
	HideInDetails?: boolean;
	TagCategoryType?: string;
	TagType?: string;
	Name?: string;
}

interface CivUnlockRow {
	CivilizationType?: string;
	CivilizationDomain?: string;
	AgeDomain?: string | null;
	AgeType?: string;
	Type?: string;
	Name?: string;
}

interface LeaderUnlockRow {
	Type?: string;
	AgeDomain?: string | null;
	AgeType?: string;
	LeaderType?: string;
}

interface CivLeaderPairingRow {
	CivilizationType?: string;
	LeaderType?: string;
}

interface CivilizationMetaRow {
	CivilizationType?: string;
	CivilizationName?: string;
	CivilizationIntroText?: string;
}

interface LeaderMetaRow {
	LeaderType?: string;
	LeaderName?: string;
}

interface TraditionRow {
	TraitType?: string;
	Name?: string;
	Description?: string;
	AgeType?: string;
	Civic?: string;
}

interface LegacyCivilizationTraitRow {
	CivilizationType?: string;
	TraitType?: string;
}

function getTypeDomainKey(type: string, domain: string | null | undefined) {
	return `${type}|${domain ?? ""}`;
}

export function createCivSelectModel() {
	// Parameter updates are polled, but some civ params get created during age transition on the frame the transition starts.
	// Force an update to ensure we have these values.
	SetupParametersModel.get().forceRefresh();

	const playerConfig = PlayerSetupParametersModel.get().players[GameContext.localPlayerID];
	const isAgeTransition = UI.isInGame();
	const playerCivilization = isAgeTransition
		? playerConfig.AgeTransitionPlayerCivilization
		: playerConfig.PlayerCivilization;
	const prevCivilization = playerConfig.PlayerCivilization;
	let prevCivInfo: CivInfo | undefined = undefined;
	const ages = AgeSelectModel.get();

	const [viewCiv, setViewCiv] = createSignal<CivInfo>();

	function resolveBonusIcon(bonus: { Kind: string; Type: string; Icon?: string }) {
		return bonus.Kind === "KIND_QUARTER" ? "CITY_UNIQUE_QUARTER" : bonus.Type;
	}

	function getCivilizations() {
		const civilizations: CivInfo[] = [];

		if (playerCivilization) {
			const civItemData = cachedCivDatabase.query(
				"select * from CivilizationItems order by SortIndex",
			) as CivItemRow[];
			const civTagData = cachedCivDatabase.query(
				"select * from CivilizationTags inner join Tags on CivilizationTags.TagType = Tags.TagType inner join TagCategories on Tags.TagCategoryType = TagCategories.TagCategoryType",
			) as CivTagRow[];
			const civUnlockData = cachedCivDatabase.query(
				"select * from CivilizationUnlocks order by SortIndex",
			) as CivUnlockRow[];
			const leaderUnlocks = cachedCivDatabase.query(
				"select * from LeaderUnlocks order by SortIndex",
			) as LeaderUnlockRow[];
			const civLeaderPairingData = cachedCivDatabase.query(
				"select * from LeaderCivParings",
			) as CivLeaderPairingRow[];
			const civilizationsData = cachedCivDatabase.query(
				"select CivilizationType, CivilizationName, CivilizationIntroText from Civilizations",
			) as CivilizationMetaRow[];
			const leadersData = cachedCivDatabase.query(
				"select LeaderType, LeaderName from Leaders",
			) as LeaderMetaRow[];

			// `LegacyCivilizationTraits` does not exist in the config database yet.  Use an empty array for now.
			const legacyCivTraitsData = [] as LegacyCivilizationTraitRow[];
			//const legacyCivTraitsData = cachedCivDatabase.query(
			//	"select CivilizationType, TraitType from LegacyCivilizationTraits",
			//) as LegacyCivilizationTraitRow[];

			const traditionsData = cachedCivDatabase.query(
				"SELECT Traditions.TraitType, Traditions.Name, Traditions.Description, Traditions.AgeType, COALESCE(Nodes.Name, IIF(Syncretism.CivilizationType IS NULL, NULL, 'LOC_UI_SYNCRETISM_TITLE')) AS Civic FROM Traditions LEFT JOIN ( SELECT * FROM ProgressionTreeNodeUnlocks INNER JOIN ProgressionTreeNodes ON ProgressionTreeNodeUnlocks.ProgressionTreeNodeType = ProgressionTreeNodes.ProgressionTreeNodeType ) AS Nodes ON Traditions.TraditionType = Nodes.TargetType LEFT JOIN CivSelfSyncretismUnlocks AS Syncretism ON Syncretism.UnlockType = Traditions.TraditionType WHERE Civic IS NOT NULL",
			) as TraditionRow[];

			const civItemsByType = new Map<string, CivItemRow[]>();
			for (const item of civItemData) {
				const civType = (item.CivilizationType as string) ?? "";
				if (!civType) {
					continue;
				}

				const items = civItemsByType.get(civType);
				if (items) {
					items.push(item);
				} else {
					civItemsByType.set(civType, [item]);
				}
			}

			const civTagsByTypeDomain = new Map<string, CivTagRow[]>();
			for (const tag of civTagData) {
				const civType = (tag.CivilizationType as string) ?? "";
				const civDomain = (tag.CivilizationDomain as string) ?? "";
				if (!civType) {
					continue;
				}

				const key = getTypeDomainKey(civType, civDomain);
				const tags = civTagsByTypeDomain.get(key);
				if (tags) {
					tags.push(tag);
				} else {
					civTagsByTypeDomain.set(key, [tag]);
				}
			}

			const civUnlocksByCivDomain = new Map<string, CivUnlockRow[]>();
			const civUnlocksByType = new Map<string, CivUnlockRow[]>();
			for (const unlock of civUnlockData) {
				const civType = (unlock.CivilizationType as string) ?? "";
				const civDomain = (unlock.CivilizationDomain as string) ?? "";
				const unlockType = (unlock.Type as string) ?? "";

				if (civType) {
					const civDomainKey = getTypeDomainKey(civType, civDomain);
					const civDomainUnlocks = civUnlocksByCivDomain.get(civDomainKey);
					if (civDomainUnlocks) {
						civDomainUnlocks.push(unlock);
					} else {
						civUnlocksByCivDomain.set(civDomainKey, [unlock]);
					}
				}

				if (unlockType) {
					const unlocks = civUnlocksByType.get(unlockType);
					if (unlocks) {
						unlocks.push(unlock);
					} else {
						civUnlocksByType.set(unlockType, [unlock]);
					}
				}
			}

			const leaderUnlocksByType = new Map<string, LeaderUnlockRow[]>();
			for (const unlock of leaderUnlocks) {
				const unlockType = (unlock.Type as string) ?? "";
				if (!unlockType) {
					continue;
				}

				const unlocks = leaderUnlocksByType.get(unlockType);
				if (unlocks) {
					unlocks.push(unlock);
				} else {
					leaderUnlocksByType.set(unlockType, [unlock]);
				}
			}

			const civLeaderPairingSet = new Set<string>();
			for (const pairing of civLeaderPairingData) {
				const civType = (pairing.CivilizationType as string) ?? "";
				const leaderType = (pairing.LeaderType as string) ?? "";
				if (!civType || !leaderType) {
					continue;
				}

				civLeaderPairingSet.add(`${civType}|${leaderType}`);
			}

			const civTraitByCivType = new Map<string, string>();
			for (const row of legacyCivTraitsData) {
				const civType = (row.CivilizationType as string) ?? "";
				const traitType = (row.TraitType as string) ?? "";
				if (!civType || !traitType) {
					continue;
				}

				civTraitByCivType.set(civType, traitType);
			}

			const civIntroTextByType = new Map<string, string>();
			const civNameByType = new Map<string, string>();
			for (const civ of civilizationsData) {
				const civType = (civ.CivilizationType as string) ?? "";
				if (!civType) {
					continue;
				}

				civIntroTextByType.set(civType, (civ.CivilizationIntroText as string) ?? "");
				civNameByType.set(civType, (civ.CivilizationName as string) ?? "");
			}

			const leaderNameByType = new Map<string, string>();
			for (const leader of leadersData) {
				const leaderType = (leader.LeaderType as string) ?? "";
				if (!leaderType) {
					continue;
				}

				leaderNameByType.set(leaderType, (leader.LeaderName as string) ?? "");
			}

			const traditionsByTrait = new Map<string, TraditionData[]>();
			for (const row of traditionsData) {
				const traitType = (row.TraitType as string) ?? "";
				if (!traitType) {
					continue;
				}

				const traditions = traditionsByTrait.get(traitType);
				const tradition = {
					title: (row.Name as string) ?? "",
					text: (row.Description as string) ?? "",
					plainText: Locale.plainText((row.Description as string) ?? ""),
					civic: (row.Civic as string) ?? "",
					age: (row.AgeType as string) ?? undefined,
				} as TraditionData;

				if (traditions) {
					traditions.push(tradition);
				} else {
					traditionsByTrait.set(traitType, [tradition]);
				}
			}

			for (const traditions of traditionsByTrait.values()) {
				// Keep existing display ordering where syncretism entries sort to the end.
				traditions.sort((a, b) => {
					if (a.civic == b.civic) return 0;
					if (a.civic == "LOC_UI_SYNCRETISM_TITLE") return 1;
					if (b.civic == "LOC_UI_SYNCRETISM_TITLE") return -1;
					return Locale.compare(a.civic, b.civic);
				});
			}

			const leaderParameter = GameSetup.findPlayerParameter(GameContext.localPlayerID, "PlayerLeader");
			const leaderType = leaderParameter ? (leaderParameter.value.value as string) : "";

			const prevCivCount: number = Configuration.getPlayer(GameContext.localPlayerID).previousCivilizationCount;
			const previousCivs = new Set<number>();

			for (let i = 0; i < prevCivCount; ++i) {
				previousCivs.add(Configuration.getPlayer(GameContext.localPlayerID).getPreviousCivilization(i));
			}

			// If a domain parameter is invalid for the following reasons, include it.  Otherwise, skip over it.
			// This is so we can visualize some reasons (locked, ownership) but ignore others (invalid, age transition).
			const invalidReasonsToInclude = new Set([
				GameSetupDomainValueInvalidReason.Valid,
				GameSetupDomainValueInvalidReason.NotValidLocked,
				GameSetupDomainValueInvalidReason.NotValidOwnership,
			]);

			if (isAgeTransition) {
				invalidReasonsToInclude.add(GameSetupDomainValueInvalidReason.NotValidAgeTransition);
			}

			for (const civData of playerCivilization.domain.possibleValues ?? []) {
				if (!invalidReasonsToInclude.has(civData.invalidReason)) {
					continue;
				}

				const civID = civData.value?.toString();
				if (!civID) {
					continue;
				}
				const civHash = Database.makeHash(civID);

				const rawName = GameSetup.resolveString(civData.name);
				if (!rawName) {
					continue;
				}

				const colors = UI.Color.getDefaultColors3DAsHex(civHash);

				const name = Locale.stylize(rawName ?? "");

				const image = GameSetup.resolveString(civData.icon);
				if (!image) {
					console.error(`age-civ-select-model: DB icon reference for civ ${name} is null`);
					continue;
				}

				const bgImage = `bg-panel-${civID.replace("CIVILIZATION_", "").toLowerCase()}`;

				const icon = UI.getIconURL(civID == "RANDOM" ? "CIVILIZATION_RANDOM" : civID, "");
				const domain = GameSetup.resolveString(civData.originDomain);

				const civTags = civTagsByTypeDomain.get(getTypeDomainKey(civID, domain)) ?? [];

				const traits = civTags
					.filter((tag) => !tag.HideInDetails && tag.TagCategoryType == "TAG_CATEGORY_TRAIT")
					.map((t) => t.Name as string);

				const age = civTags
					.filter((tag) => tag.HideInDetails && tag.TagCategoryType == "TAG_CATEGORY_APEX_AGE")
					.map((t) => (t.TagType as string)?.replace("TAG_APEX_", ""));

				const apexAge = age?.length > 0 ? age[0] : "AGE_ANTIQUITY";

				const ageSortIndex = ages.sortedAges.findIndex((age) => age.type == apexAge);
				const ageInfo = ages.sortedAges[ageSortIndex];
				const ageID = ageInfo?.type ?? "";
				const ageName = ageInfo?.name ?? "";

				const introText = civIntroTextByType.get(civID) ?? "";

				const valueUnlocks = (civUnlocksByCivDomain.get(getTypeDomainKey(civID, domain)) ?? []).filter(
					(unlock) =>
						unlock.AgeDomain == null ||
						ages.sortedAges.find((age) => age.type == unlock.AgeType)?.domain == unlock.AgeDomain,
				);

				valueUnlocks.sort((a, b) =>
					(a.AgeType as string) == (b.AgeType as string)
						? Locale.compare(a.Type as string, b.Type as string)
						: Locale.compare(a.AgeType as string, b.AgeType as string),
				);

				const unlocks: string[] = valueUnlocks.map((unlock) => {
					const ageName = unlock.AgeDomain ? ages.getAgeName(unlock.AgeType as string) : null;
					return ageName
						? Locale.stylize("LOC_CREATE_GAME_UNLOCK_ITEM_IN_AGE", unlock.Name as string, ageName)
						: Locale.stylize("LOC_CREATE_GAME_UNLOCK_ITEM", unlock.Name as string);
				});

				const civItems = civItemsByType.get(civID) ?? [];

				const abilityData = civItems.filter((item) => item.Kind == "KIND_TRAIT");
				const perAgeAbilities = abilityData.map((ability) => ({
					abilityTextTag: ability?.Description,
					abilityTitle: Locale.stylize((ability?.Name as string) ?? ""),
					abilityText: Locale.stylize((ability?.Description as string) ?? ""),
					abilityPlainText: Locale.plainText((ability?.Description as string) ?? ""),
					age: ability?.AgeType as string,
				}));

				const buildings: CivBonusData[] = civItems
					.filter(
						(item) =>
							item.Kind == "KIND_BUILDING" ||
							item.Kind == "KIND_IMPROVEMENT" ||
							item.Kind == "KIND_QUARTER" ||
							item.Kind == "KIND_ROUTE",
					)
					.map((item) => ({
						title: Locale.stylize((item.Name as string) ?? ""),
						icon: resolveBonusIcon(item as { Kind: string; Type: string; Icon?: string }),
						text: Locale.stylize((item.Description as string) ?? ""),
						plainText: Locale.plainText((item.Description as string) ?? ""),
						description: (item.Description as string) ?? "",
						kind: (item.Kind as string) ?? "",
						age: (item.AgeType as string) ?? undefined,
					}));

				const units: CivBonusData[] = civItems
					.filter((item) => item.Kind == "KIND_UNIT")
					.map((item) => ({
						title: Locale.stylize((item.Name as string) ?? ""),
						icon: resolveBonusIcon(item as { Kind: string; Type: string; Icon?: string }),
						text: Locale.stylize((item.Description as string) ?? ""),
						plainText: Locale.plainText((item.Description as string) ?? ""),
						description: (item.Description as string) ?? "",
						kind: (item.Kind as string) ?? "",
						age: (item.AgeType as string) ?? undefined,
					}));

				// check if restricted leader live event is running, then only show fixed civ
				if (LiveEventManager.restrictToPreferredCivs()) {
					const hasFixedPairing = civLeaderPairingSet.has(`${civID}|${leaderType}`);

					if (!hasFixedPairing && !UI.isMultiplayer())
						// different behavior for MP because of tooltips data
						continue;
				}

				const isLocked = civData.invalidReason != GameSetupDomainValueInvalidReason.Valid;
				const isOwned = civData.invalidReason != GameSetupDomainValueInvalidReason.NotValidOwnership;

				const unlocksByCiv: UnlockedByData[] = (civUnlocksByType.get(civID) ?? [])
					.filter(
						(unlock) =>
							unlock.AgeDomain == null ||
							ages.sortedAges.find((a) => a.type == (unlock.AgeType as string))?.domain ==
								unlock.AgeDomain,
					)
					.map((civ) => {
						const civId = Database.makeHash((civ.CivilizationType as string) ?? "");
						return {
							text: Locale.compose(
								"LOC_AGE_TRANSITION_PLAY_AS",
								civNameByType.get((civ.CivilizationType as string) ?? "") ?? "",
							),
							isUnlocked: previousCivs.has(civId),
						};
					});

				const unlocksByLeader: UnlockedByData[] = (leaderUnlocksByType.get(civID) ?? [])
					.filter(
						(unlock) =>
							unlock.AgeDomain == null ||
							ages.sortedAges.find((a) => a.type == (unlock.AgeType as string))?.domain ==
								unlock.AgeDomain,
					)
					.map((unlock) => {
						return {
							text: Locale.compose(
								"LOC_AGE_TRANSITION_PLAY_AS",
								leaderNameByType.get((unlock.LeaderType as string) ?? "") ?? "",
							),
							isUnlocked: leaderType == unlock.LeaderType,
						};
					});

				const unlockedBy = [...unlocksByCiv, ...unlocksByLeader];

				const civTrait = civTraitByCivType.get(civID) ?? civID.replace("CIVILIZATION_", "TRAIT_");
				const traditions: TraditionData[] = civTrait ? (traditionsByTrait.get(civTrait) ?? []) : [];

				const fulltext = Locale.toLower(
					[
						name,
						perAgeAbilities.map((b) => `${b.abilityTitle} ${b.abilityPlainText}`).join(" "),
						traits.map((t) => Locale.plainText(t)).join(" "),
						buildings.map((b) => `${b.title} ${b.plainText}`).join(" "),
						units.map((u) => `${u.title} ${u.plainText}`).join(" "),
						traditions.map((t) => `${Locale.plainText(t.title)} ${t.plainText}`).join(" "),
					].join(" "),
				);

				const civInfo = {
					civID: civID,
					name,
					icon: icon ?? "",
					bgImage,
					perAgeAbilities,
					buildings: buildings,
					units: units,
					traits: traits,
					traditions,
					isLocked: isLocked,
					isOwned: isOwned,
					apexAge: ageID,
					ageSortIndex,
					ageName,
					fulltext,
					colors,
					introText,
					unlocks,
					unlockedBy,
				} as CivInfo;

				if (prevCivilization.value.value == civID) {
					prevCivInfo = civInfo;
				}

				civilizations.push(civInfo);
			}
		}

		return civilizations;
	}

	const civs = getCivilizations();
	const mutableCivs = createMutable(civs);

	createEffect(() => {
		const updatedCivs = getCivilizations();
		modifyMutable(mutableCivs, reconcile(updatedCivs));
	});

	const previousCiv = createMemo(() => prevCivInfo);

	const selectedCiv = createMemo(() => civs.find((c) => c.civID == playerCivilization.value.value) ?? civs[0]);

	function setSelectedCiv(civ: CivInfo) {
		playerCivilization.setValue(civ.civID);
	}

	const selectedIndex = createMemo(() => civs.findIndex((c) => selectedCiv().civID == c.civID));

	const selectNext = () => {
		let newIndex = selectedIndex() + 1;
		if (newIndex >= civs.length) {
			newIndex = 0;
		}
		setSelectedCiv(civs[newIndex]);
	};

	const selectPrev = () => {
		let newIndex = selectedIndex() - 1;
		if (newIndex < 0) {
			newIndex = civs.length - 1;
		}
		setSelectedCiv(civs[newIndex]);
	};

	// eslint-disable-next-line solid/reactivity
	const randomCiv = mutableCivs.find((c) => c.civID == "RANDOM");

	const search = new FullTextSearch("CivSelectFilter");
	search.addSearchData(civs.map((c) => ({ key: c.civID, title: c.name, fullText: c.fulltext })));
	const fulltextSearch = (text: string) => search.find(text);

	return {
		civs: mutableCivs,
		randomCiv,
		previousCiv,
		selectedCiv,
		setSelectedCiv,
		selectNext,
		selectPrev,
		viewCiv,
		setViewCiv,
		fulltextSearch,
	} as CivSelectModel;
}

//MARK: AGE  FILTER
export const createAgeFilterModel = (() => {
	let model: AgeFilterModel | null = null;

	return function (): AgeFilterModel {
		if (model) return model;

		const ageModel = useAgeSelectModelContext();
		const isAgeTransition = UI.isInGame();

		const options: AgeFilterItem[] = [
			{ ageId: "ALL", name: Locale.compose("LOC_UI_CREATE_GAME_FILTER_ALL_AGES").toUpperCase() },
			...ageModel.sortedAges.map((a) => ({ ageId: a.type, name: Locale.compose(a.name).toUpperCase() })),
		];

		const defaultAgeFilter = isAgeTransition
			? (options.find((a) => a.ageId == ageModel.nextAge.type) ?? options[0])
			: options[0];

		const [selected, setSelected] = createSignal<AgeFilterItem>(defaultAgeFilter);

		function isMatch(ageId: string) {
			const selectedId = selected().ageId;
			return selectedId == "ALL" || selectedId == ageId;
		}

		function reset() {
			setSelected(defaultAgeFilter);
		}

		model = {
			selected,
			setSelected,
			options,
			isMatch,
			reset,
		};
		return model;
	};
})();

//MARK: ATTRibutes FILTER
const [getFilter, setFilter] = createSignal<string | undefined>("LOC_LEGACIES_FILTER_ALL_ATTRIBUTES");

export const attrFilter = {
	getFilter,
	setFilter,
	reset: () => setFilter("LOC_LEGACIES_FILTER_ALL_ATTRIBUTES"),
};

export const CivSelectModel = ModelRegistry.register(
	"CivSelectModel",
	ModelLifecycle.SharedInstance,
	createCivSelectModel,
);

export const CivSelectModelContext = createContext<CivSelectModel>();

export function useCivSelectModelContext() {
	const context = useContext(CivSelectModelContext);

	if (!context) {
		throw new Error("useCivSelectModel: Cannot find context!");
	}

	return context;
}

export interface AgeFilterItem {
	ageId: string;
	name: string;
}

